def is_balanced(s):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    stack = []
    for ch in s:
        if is_bracket(ch):
            if ch in OPEN:
                stack.append(ch)
            else:  # ch in CLOSE
                if not stack or stack[-1] != PAIRS[ch]:
                    return False
                stack.pop()
    return not stack
